<template>
  <DrillingPageFrame title="系统配置">
    <el-alert v-if="!fieldId" title="暂无可配置的工程范围" type="warning" :closable="false" />
    <section v-else class="config-layout">
      <div class="panel"><div class="panel-title"><span>当前配置 v{{ currentConfig?.config_version || '—' }}</span><el-button type="primary" :loading="saving" v-if="canConfigure" @click="save">保存新版本</el-button></div>
        <el-form :disabled="!canConfigure" :model="configForm" label-position="top" class="config-form">
          <el-tabs v-model="configTab">
          <el-tab-pane label="坐标与测量" name="0"><div class="config-section"><div class="field-grid">
            <el-form-item label="坐标轴约定"><el-select v-model="configForm.coordinateSystem"><el-option label="N/E/TVD 向下" value="NED"/><el-option label="本地工程坐标" value="LOCAL_ENU"/></el-select></el-form-item><el-form-item label="坐标参考系（如 EPSG:32631）"><el-input v-model="configForm.algorithmDefaults.reference.crs" placeholder="本地坐标可留空，跨参考系评价须配置"/></el-form-item><el-form-item label="深度基准名称"><el-input v-model="configForm.algorithmDefaults.reference.depth_datum" /></el-form-item><el-form-item label="深度基准高程（m）"><el-input-number v-model="configForm.algorithmDefaults.reference.depth_datum_elevation_m" /></el-form-item>
            <el-form-item label="北向基准"><el-select v-model="configForm.northReference"><el-option label="TRUE_NORTH" value="TRUE_NORTH"/><el-option label="GRID_NORTH" value="GRID_NORTH"/><el-option label="MAGNETIC_NORTH" value="MAGNETIC_NORTH"/></el-select></el-form-item>
            <el-form-item label="长度单位"><el-input v-model="configForm.lengthUnit" /></el-form-item><el-form-item label="角度单位"><el-input v-model="configForm.angleUnit" /></el-form-item><el-form-item label="TVD 正方向"><el-select v-model="configForm.tvdPositive"><el-option label="向下 D" value="D"/><el-option label="向上 U" value="U"/></el-select></el-form-item>
            <el-form-item label="原点 North（m）"><el-input-number v-model="configForm.originNorth" /></el-form-item><el-form-item label="原点 East（m）"><el-input-number v-model="configForm.originEast" /></el-form-item><el-form-item label="原点 TVD（m）"><el-input-number v-model="configForm.originTvd" /></el-form-item><el-form-item label="磁偏角（deg）"><el-input-number v-model="configForm.magneticDeclination"/></el-form-item><el-form-item label="子午线收敛角（deg）"><el-input-number v-model="configForm.meridianConvergence"/></el-form-item>
          </div></div></el-tab-pane>
          <el-tab-pane label="防碰评价与误差模型" name="1"><div class="config-section"><div class="field-grid">
            <el-form-item v-if="sfParameterKeys.includes('k')" label="不确定性放大系数 K"><el-input-number v-model="configForm.algorithmDefaults.errorModel.k" :min="0.01" :step="0.1" /></el-form-item>
            <el-form-item label="轨道不确定性模型"><el-select :model-value="configForm.algorithmDefaults.errorModel.modelVersion" @change="changeModel"><el-option v-for="m in catalog.models" :key="m.name" :label="errorModelName(m.name)" :value="m.name" /></el-select></el-form-item>
            <el-form-item label="扫描步长（m）"><el-input-number v-model="configForm.algorithmDefaults.scanStep" :min="0.1" :step="0.5"/></el-form-item><el-form-item label="评价方式"><el-tag type="success">井间距法 / 分离系数法</el-tag></el-form-item>
            <el-form-item class="formula-field" label="分离系数计算公式"><div class="formula-readonly"><code>{{ sfFormula?.formula || '—' }}</code><span>{{ sfFormula?.definition || '—' }}</span></div></el-form-item>
            <el-form-item v-if="sfParameterKeys.includes('radiiMarginM')" label="两井物理半径与附加裕量之和（m）"><el-input-number v-model="configForm.algorithmDefaults.errorModel.radiiMarginM" :min="0" :step="0.1" /></el-form-item>
            <el-form-item v-if="sfParameterKeys.includes('sigmaPaM')" label="附加位置标准差 σpa（m）"><el-input-number v-model="configForm.algorithmDefaults.errorModel.sigmaPaM" :min="0" :step="0.01" /></el-form-item>
            <el-form-item label="曲线离散几何容差（m）"><el-input-number v-model="configForm.algorithmDefaults.errorModel.curveToleranceM" :min="0.00001" :step="0.001" /></el-form-item>
          </div><el-descriptions :column="1" border class="mb16"><el-descriptions-item label="计算公式">{{ sfFormula?.formula }}</el-descriptions-item><el-descriptions-item label="参数含义">{{ sfFormula?.definition }}</el-descriptions-item></el-descriptions>
          <h4>误差模型计算参数</h4><ParameterFields v-model="configForm.algorithmDefaults.errorModel.settings" />
          <el-collapse><el-collapse-item title="完整模型配置（JSON，可编辑所有原生字段）"><el-input v-model="settingsJson" type="textarea" :autosize="{minRows:10,maxRows:25}" @change="applySettingsJson" /></el-collapse-item></el-collapse>
          </div></el-tab-pane>
          <el-tab-pane label="风险阈值" name="2"><div class="config-section"><div class="field-grid"><el-form-item label="邻井搜索外扩距离（m）"><el-input-number v-model="configForm.algorithmDefaults.neighborSearchMarginM" :min="0" :step="50" /></el-form-item><el-form-item label="红色 SF"><el-input-number v-model="configForm.algorithmDefaults.thresholds.redSf" :min="0"/></el-form-item><el-form-item label="橙色 SF"><el-input-number v-model="configForm.algorithmDefaults.thresholds.orangeSf" :min="0"/></el-form-item><el-form-item label="黄色 SF"><el-input-number v-model="configForm.algorithmDefaults.thresholds.yellowSf" :min="0"/></el-form-item><el-form-item label="红色中心距（m）"><el-input-number v-model="configForm.algorithmDefaults.thresholds.redDistance" :min="0"/></el-form-item><el-form-item label="误差净比橙色"><el-input-number v-model="configForm.algorithmDefaults.thresholds.errorNetRatioOrange" :min="0"/></el-form-item><el-form-item label="误差净比黄色"><el-input-number v-model="configForm.algorithmDefaults.thresholds.errorNetRatioYellow" :min="0"/></el-form-item></div></div></el-tab-pane>
          <el-tab-pane label="轨迹再规划" name="3"><div class="config-section"><div class="field-grid"><el-form-item label="原生轨迹模型"><el-select v-model="configForm.algorithmDefaults.planning.nativeOptions.trajectory_mode"><el-option v-for="mode in catalog.trajectory_modes" :key="mode" :label="({arc:'圆弧','arc-straight':'圆弧—直线','straight-arc':'直线—圆弧'}[mode]||mode)" :value="mode"/></el-select></el-form-item><el-form-item label="原生轨迹段数"><el-select v-model="configForm.algorithmDefaults.planning.nativeOptions.n_segments"><el-option v-for="count in catalog.segment_counts" :key="count" :label="`${count} 段`" :value="count"/></el-select></el-form-item><el-form-item label="求解器"><el-select v-model="configForm.algorithmDefaults.planning.solver"><el-option v-for="solver in catalog.algorithms" :key="solver" :label="solver" :value="solver"/></el-select></el-form-item><el-form-item label="碰撞约束"><el-tag type="success">分离系数法</el-tag></el-form-item><el-form-item label="最大狗腿度（deg/30m）"><el-input-number v-model="configForm.algorithmDefaults.planning.maxDoglegDegPer30m" :min="0.1" :step="0.1"/></el-form-item><el-form-item label="最小狗腿度（deg/30m）"><el-input-number v-model="configForm.algorithmDefaults.planning.minDoglegDegPer30m" :min="0" :step="0.1"/></el-form-item><el-form-item label="最小段长（m）"><el-input-number v-model="configForm.algorithmDefaults.planning.minSegmentLength" :min="0.1"/></el-form-item><el-form-item label="最大段长（m）"><el-input-number v-model="configForm.algorithmDefaults.planning.maxSegmentLength" :min="0.1"/></el-form-item><el-form-item label="最大工具面变化（deg）"><el-input-number v-model="configForm.algorithmDefaults.planning.maxToolfaceChangeDeg" :min="0" :max="360"/></el-form-item><el-form-item label="最低 SF"><el-input-number v-model="configForm.algorithmDefaults.planning.minimumSf" :min="0.01" :step="0.1"/></el-form-item><el-form-item label="目标容差（m）"><el-input-number v-model="configForm.algorithmDefaults.planning.targetToleranceM" :min="0.01" :step="0.1"/></el-form-item><el-form-item label="任务时限（s）"><el-input-number v-model="configForm.algorithmDefaults.planning.taskTimeoutSeconds" :min="5" :max="300" /></el-form-item><el-form-item label="最大迭代次数"><el-input-number v-model="configForm.algorithmDefaults.planning.maxIterations" :min="1" :max="5000"/></el-form-item></div><el-alert title="轨迹模型和段数使用 well_control_iscwsa 引擎目录中的原生选项；当前井场配置作为再规划任务的默认值。" type="info" :closable="false"/><ParameterFields v-model="configForm.algorithmDefaults.planning.nativeOptions" :exclude="['trajectory_mode','n_segments']" /></div></el-tab-pane>
          <el-tab-pane label="实时姿态预测与报警" name="4"><div class="config-section"><div class="field-grid"><el-form-item label="预测步长（m）"><el-input-number v-model="configForm.algorithmDefaults.prediction.predictionStep" :min="0.1" :max="1000" :step="1"/></el-form-item><el-form-item label="训练模型版本"><el-select v-model="configForm.algorithmDefaults.prediction.modelVersionId" clearable filterable placeholder="不选择时使用几何回退" @clear="configForm.algorithmDefaults.prediction.modelVersionId=null"><el-option v-for="model in models" :key="model.model_version_id" :label="`${model.model_name} · v${model.version_no}`" :value="model.model_version_id"/></el-select></el-form-item><el-form-item label="姿态推理模板"><el-select v-model="configForm.algorithmDefaults.prediction.templateRuntimePath" clearable filterable placeholder="请选择推理适配器"><el-option v-for="template in templates" :key="template.template_id" :label="`${template.template_name} · ${template.runtime_path}`" :value="template.runtime_path"/></el-select></el-form-item><el-form-item label="推理设备"><el-select v-model="configForm.algorithmDefaults.prediction.device"><el-option label="自动" value="auto"/><el-option label="CPU" value="cpu"/><el-option label="GPU 0" value="cuda:0"/></el-select></el-form-item><el-form-item label="推理超时（秒）"><el-input-number v-model="configForm.algorithmDefaults.prediction.timeoutSeconds" :min="1" :max="300"/></el-form-item><el-form-item label="模型失败后回退"><el-switch v-model="configForm.algorithmDefaults.prediction.allowFallback"/></el-form-item><el-form-item label="回退方式"><el-tag>切向外推</el-tag></el-form-item><el-form-item label="弹窗报警"><el-switch v-model="configForm.algorithmDefaults.prediction.popupAlarmEnabled"/></el-form-item><el-form-item label="声音报警"><el-switch v-model="configForm.algorithmDefaults.prediction.soundAlarmEnabled"/></el-form-item><el-form-item label="最低报警等级"><el-select v-model="configForm.algorithmDefaults.prediction.alertMinimumLevel"><el-option label="黄色及以上" value="YELLOW"/><el-option label="橙色及以上" value="ORANGE"/><el-option label="红色" value="RED"/></el-select></el-form-item></div><el-alert v-if="!models.length || !templates.length" title="训练模型或推理模板尚未登记" type="info" :closable="false">请在模型仓库登记模型与推理适配器。</el-alert></div></el-tab-pane>
          </el-tabs>
        </el-form>
      </div>
      <div class="panel"><div class="panel-title">配置版本</div><el-table :data="versions"><el-table-column prop="config_version" label="版本" width="80"/><el-table-column prop="coordinate_system" label="坐标系"/><el-table-column prop="status" label="状态" width="80"/><el-table-column prop="create_time" label="创建时间" min-width="160"/><el-table-column label="操作" width="100"><template #default="s"><el-button v-if="canConfigure && String(s.row.status)!=='0'" link type="primary" @click="activate(s.row.config_version)">启用</el-button></template></el-table-column></el-table></div>
    </section>
  </DrillingPageFrame>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { activateFieldConfig, createFieldConfig, getCurrentFieldConfig, listFieldConfigs, listTrainingTemplates } from '@/api/drillingField'
import { listModels } from '@/api/drilling'
import DrillingPageFrame from '../layout/DrillingPageFrame.vue'
import ParameterFields from '../layout/ParameterFields.vue'
import {engineCatalog} from '@/api/drillingRegistry'
import {errorModelName,separationFactorDetails,separationFactorParameterKeys} from '@/utils/engineeringErrorModels'
import { useDrillingContext } from '../composables/useDrillingContext'
const catalog=ref({models:[],algorithms:['SLSQP'],sf_methods:[]})
const route=useRoute()
const sfFormula=computed(()=>separationFactorDetails(configForm.algorithmDefaults.errorModel)),settingsJson=ref('')
const sfParameterKeys=computed(()=>separationFactorParameterKeys(configForm.algorithmDefaults.errorModel))
function syncSettingsJson(){settingsJson.value=JSON.stringify(configForm.algorithmDefaults.errorModel.settings,null,2)}
function applySettingsJson(value){try{const s=JSON.parse(value);if(!catalog.value.models.some(m=>m.name===s.uncertainty_model?.type))throw Error('请选择支持的轨道不确定性模型');configForm.algorithmDefaults.errorModel.settings=s;configForm.algorithmDefaults.errorModel.modelVersion=s.uncertainty_model.type;syncSettingsJson()}catch(e){ElMessage.error('模型配置无效：'+e.message)}}
function changeModel(name){const model=catalog.value.models.find(m=>m.name===name);if(model){configForm.algorithmDefaults.errorModel.modelVersion=name;configForm.algorithmDefaults.errorModel.mode=name==='md_scalar_radius'?'NATIVE_RADIUS':'ISCWSA';configForm.algorithmDefaults.errorModel.settings=JSON.parse(JSON.stringify(model.settings));syncSettingsJson()}}
const { fieldId, canConfigure, currentConfig, configForm, loadFields, loadFieldContext } = useDrillingContext(); const versions=ref([]); const models=ref([]); const templates=ref([]); const saving=ref(false); const configTab=ref(route.query.tab==='errorModel'?'1':'0')
async function load(){if(!fieldId.value)return;const [configResult,modelResult,templateResult]=await Promise.allSettled([listFieldConfigs(fieldId.value),listModels(fieldId.value),listTrainingTemplates(fieldId.value)]);if(configResult.status==='fulfilled')versions.value=configResult.value||[];if(modelResult.status==='fulfilled')models.value=modelResult.value?.models||[];if(templateResult.status==='fulfilled')templates.value=templateResult.value||[];await getCurrentFieldConfig(fieldId.value)}
async function save(){if(!fieldId.value)return;const prediction=configForm.algorithmDefaults.prediction;if(prediction.modelVersionId&&!prediction.templateRuntimePath){ElMessage.warning('选择训练模型版本后，还需要选择姿态推理模板');return}saving.value=true;try{await createFieldConfig(fieldId.value,{...configForm,algorithmDefaults:configForm.algorithmDefaults});await loadFieldContext();await load();ElMessage.success('配置版本已创建')}catch(e){ElMessage.error(e.message||'配置保存失败')}finally{saving.value=false}}
async function activate(version){try{await activateFieldConfig(fieldId.value,version);await loadFieldContext();await load();ElMessage.success(`已启用配置 v${version}`)}catch(e){ElMessage.error(e.message||'配置启用失败')}}
watch(fieldId,async()=>{await load();syncSettingsJson()});watch(()=>configForm.algorithmDefaults.errorModel.settings,syncSettingsJson,{deep:true});watch(()=>route.query.tab,value=>{if(value==='errorModel')configTab.value='1'});onMounted(async()=>{try{catalog.value=await engineCatalog()}catch(e){ElMessage.error('读取引擎配置失败：'+e.message)}if(!fieldId.value)await loadFields();await load();syncSettingsJson()})
</script>

<style scoped>.config-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(360px,.7fr);gap:14px}.panel{padding:16px;border:1px solid var(--el-border-color-light);background:var(--el-bg-color);min-width:0}.panel-title{display:flex;justify-content:space-between;color:var(--el-text-color-primary);font-weight:600;margin-bottom:14px}.config-form{min-width:0}.config-form :deep(.el-tabs__nav-wrap){max-width:100%}.config-section{padding:14px 0;border-top:1px solid var(--el-border-color-light)}.config-section:first-child{border-top:0;padding-top:0}.config-section h3,.config-section h4{margin:0 0 12px;color:var(--el-text-color-primary)}.config-section h4{font-size:12px;color:var(--el-text-color-regular)}.formula-field{grid-column:1/-1}.formula-readonly{display:flex;flex-direction:column;gap:6px;width:100%;padding:10px 12px;border:1px solid var(--el-border-color);background:var(--el-fill-color-lighter);line-height:1.6}.formula-readonly code{font-size:14px;color:var(--el-text-color-primary);white-space:normal;overflow-wrap:anywhere}.formula-readonly span{font-size:12px;color:var(--el-text-color-regular)}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}.field-grid :deep(.el-input-number),.field-grid :deep(.el-select),.field-grid :deep(.el-input){width:100%}.field-grid :deep(.el-tag){white-space:nowrap}@media(max-width:1200px){.field-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:900px){.config-layout{grid-template-columns:1fr}.field-grid{grid-template-columns:1fr}}
</style>
